
/* Secure Loader */
(function() {
    var _encData = "";
    function _run(CryptoJS) {
        var _decrypt = function(p) {
            try {
                var bytes = CryptoJS.AES.decrypt(_encData, p);
                var str = bytes.toString(CryptoJS.enc.Utf8);
                if (!str || str.length < 5) throw "err";
                return str;
            } catch (e) { return null; }
        };
        var key = sessionStorage.getItem("miu_key");
        var code = key ? _decrypt(key) : null;
        if (code) { new Function(code)(); return; }

        var input = prompt("此程序受保护，请输入启动密码:");
        if (input) {
            code = _decrypt(input);
            if (code) {
                sessionStorage.setItem("miu_key", input);
                new Function(code)();
            } else {
                alert("密码错误");
                location.reload();
            }
        } else {
             document.body.innerHTML = "<div style='display:flex;justify-content:center;align-items:center;height:100vh;background:#111;color:#666'>已取消加载</div>";
        }
    }
    if (typeof CryptoJS === 'undefined') {
        var s = document.createElement('script');
        s.src = 'https://cdnjs.cloudflare.com/ajax/libs/crypto-js/4.1.1/crypto-js.min.js';
        s.onload = function() { _run(window.CryptoJS); };
        document.head.appendChild(s);
    } else {
        _run(CryptoJS);
    }
})();